-- =========================================================================
-- STANDALONE SQL IMPORT FOR AI-901: Microsoft Azure AI Fundamentals
-- Total questions: 128 questions
-- Default status: is_disabled = true
-- =========================================================================

BEGIN;

-- 1. Ensure custom_certificates table has is_disabled & badge column
ALTER TABLE public.custom_certificates ADD COLUMN IF NOT EXISTS is_disabled BOOLEAN DEFAULT false;
ALTER TABLE public.custom_certificates ADD COLUMN IF NOT EXISTS badge TEXT DEFAULT 'none';

-- 2. Upsert Certificate metadata
INSERT INTO public.custom_certificates (
  id, name, code, description, difficulty, estimated_hours, color_class, icon_name, is_vip, is_disabled, badge
) VALUES (
  'ai-901',
  'Microsoft Azure AI Fundamentals',
  'AI-901',
  'Chinh phục chứng chỉ Microsoft Azure AI Fundamentals (AI-901). Khái niệm trí tuệ nhân tạo, Machine Learning, Computer Vision, Natural Language Processing và Responsible AI trên Azure.',
  'Cơ bản',
  '8-12 Giờ',
  'bg-gradient-to-br from-teal-500 to-cyan-600 text-white',
  'Award',
  false,
  true,
  'new'
) ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  code = EXCLUDED.code,
  description = EXCLUDED.description,
  difficulty = EXCLUDED.difficulty,
  estimated_hours = EXCLUDED.estimated_hours,
  color_class = EXCLUDED.color_class,
  icon_name = EXCLUDED.icon_name,
  badge = EXCLUDED.badge;

-- 3. Upsert Questions
INSERT INTO public.questions (
  id, cert_id, question_number, text, options,
  correct_answers, explanation, category, tags, image_url, status
) VALUES
  ('ai901-1', 'ai-901', 1, 'You need to transform written customer notifications into natural-sounding spoken audio for playback through a phone system.  
  
Which Azure Speech in Foundry Tools capability should you use?', '[{"key":"A","text":"speech recognition"},{"key":"B","text":"speech synthesis"},{"key":"C","text":"speaker recognition"},{"key":"D","text":"speech translation"}]'::jsonb, ARRAY['B']::text[], 'Tổng hợp giọng nói, còn được gọi là văn bản thành giọng nói, chuyển đổi văn bản viết thành âm thanh giọng nói tổng hợp giống như con người, bao gồm cả để phát lại ứng dụng và hệ thống điện thoại.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-2', 'ai-901', 2, 'You have a Microsoft Foundry project containing a vision-enabled model deployment.  
  
You use the Azure OpenAI Responses API to send a prompt to the model. You need to supply an image for analysis.  
  
Which content item should be included in the request?', '[{"key":"A","text":"image_generation"},{"key":"B","text":"output_image"},{"key":"C","text":"input_image"},{"key":"D","text":"image_base64"}]'::jsonb, ARRAY['C']::text[], 'Đối với mô hình hỗ trợ tầm nhìn, API phản hồi Azure OpenAI sử dụng mục nội dung `input_image` để cung cấp hình ảnh để phân tích. Trường `image_url` của nó có thể chứa URL hình ảnh hoặc hình ảnh được mã hóa Base64 dưới dạng URL dữ liệu.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-3', 'ai-901', 3, 'For each of the following statements, select **Yes** if the statement is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"System prompts can be used to authorize users.","correctAnswer":"No"},{"id":"2","text":"A system prompt is used to reduce tokens per minute (TPM).","correctAnswer":"No"},{"id":"3","text":"A system prompt guides the behavior of a generative AI model.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:No', '2:No', '3:Yes']::text[], 'Lời nhắc hệ thống cung cấp hướng dẫn và ngữ cảnh điều khiển hành vi của mô hình, chẳng hạn như vai trò, giai điệu, ranh giới và định dạng đầu ra. Chúng không xác thực hoặc ủy quyền cho người dùng, điều này phải được thực thi bởi cơ chế nhận dạng và kiểm soát quyền truy cập của ứng dụng. Lời nhắc hệ thống sử dụng mã thông báo ngữ cảnh/đầu vào thay vì giảm giới hạn mã thông báo mỗi phút.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-4', 'ai-901', 4, 'You are building an application that analyzes voicemail recordings by using Azure Content Understanding in Foundry Tools.  
  
You need to extract a transcript and structured data from the recordings.  
  
Which analyzer type should you use?', '[{"key":"A","text":"document analyzer"},{"key":"B","text":"video analyzer"},{"key":"C","text":"audio analyzer"},{"key":"D","text":"image analyzer"}]'::jsonb, ARRAY['C']::text[], 'Bộ phân tích âm thanh trong Nội dung Azure Hiểu về phiên âm âm thanh hội thoại và trích xuất các trường có cấu trúc từ tệp âm thanh, giúp chúng phù hợp cho bản ghi thư thoại.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-5', 'ai-901', 5, 'Select the answer that correctly finishes the sentence.', '[]'::jsonb, ARRAY[]::text[], 'AI sáng tạo tạo nội dung mới từ lời nhắc của người dùng hoặc đầu vào khác. Hiểu nội dung, trích xuất thông tin và phân tích văn bản thay vào đó diễn giải hoặc lấy thông tin từ nội dung hiện có.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-6', 'ai-901', 6, 'You are reviewing best practices for using AI at your company.  
  
Which Microsoft responsible AI principle does each task demonstrate? Each principle may be used once, more than once, or not at all.', '{"statements":[{"id":"slot1","text":"Evaluating model outputs to ensure that decisions are NOT biased against specific demographic groups:","correctAnswer":"B"},{"id":"slot2","text":"Encrypting sensitive customer data and restricting system access to authorized personnel:","correctAnswer":"D"},{"id":"slot3","text":"Informing users when they are interacting with an AI system and explaining the system''s capabilities and limitations:","correctAnswer":"F"},{"id":"slot4","text":"Testing AI systems under different conditions to reduce unexpected failures:","correctAnswer":"E"}],"choices":[{"key":"A","text":"Accountability"},{"key":"B","text":"Fairness"},{"key":"C","text":"Inclusiveness"},{"key":"D","text":"Privacy and security"},{"key":"E","text":"Reliability and safety"},{"key":"F","text":"Transparency"}]}'::jsonb, ARRAY['slot1=B', 'slot2=D', 'slot3=F', 'slot4=E']::text[], 'Sự công bằng đòi hỏi phải xác định và giảm thiểu các kết quả sai lệch giữa các nhóm nhân khẩu học. Quyền riêng tư và bảo mật bảo vệ dữ liệu nhạy cảm thông qua các biện pháp như mã hóa và kiểm soát truy cập. Tính minh bạch bao gồm việc thông báo cho mọi người khi họ tương tác với AI cũng như truyền đạt các khả năng và hạn chế của nó. Độ tin cậy và an toàn đòi hỏi phải kiểm tra hệ thống AI trong các điều kiện để giảm thiểu lỗi và hành vi không an toàn.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-7', 'ai-901', 7, 'What are two purposes of instructions when you prompt a generative AI model? Each correct answer represents part of the solution.  
  
NOTE: Each correct selection is worth one point.', '[{"key":"A","text":"defines the agent’s role and behavior"},{"key":"B","text":"selects which model to use"},{"key":"C","text":"defines the Azure region where inference occurs"},{"key":"D","text":"defines the tokens per minute (TPM) allocation for the model"},{"key":"E","text":"defines constraints on the model’s responses"}]'::jsonb, ARRAY['A', 'E']::text[], 'Hướng dẫn nhanh chóng cung cấp hướng dẫn liên tục về vai trò, hành vi và ranh giới của trợ lý, đồng thời họ có thể chỉ định các ràng buộc kiểm soát hoặc hạn chế phản hồi của trợ lý. Lựa chọn mô hình, vùng suy luận Azure và phân bổ mã thông báo mỗi phút được định cấu hình bên ngoài lời nhắc.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-8', 'ai-901', 8, 'For each statement below, select **Yes** when it is true; otherwise, select **No**.', '{"statements":[{"id":"1","text":"In the Foundry playground, you can upload a local image and include text in the same message when prompting a multimodal model.","correctAnswer":"Yes"},{"id":"2","text":"When using the OpenAI Responses API and a vision-enabled model, images can be provided only as base64-encoded image data.","correctAnswer":"No"},{"id":"3","text":"Prompts that include images require deploying a text-only model because multimodal capabilities are handled by the application layer.","correctAnswer":"No"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:No', '3:No']::text[], 'Sân chơi Azure AI Foundry hỗ trợ các lời nhắc đa phương thức chứa nội dung hình ảnh và văn bản. API phản hồi chấp nhận đầu vào hình ảnh dưới dạng URL bên ngoài, URL dữ liệu base64 hoặc ID tệp đã tải lên. Đầu vào hình ảnh được xử lý bằng các mô hình đa phương thức có khả năng hiển thị chứ không phải triển khai chỉ bằng văn bản.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-9', 'ai-901', 9, 'You are developing a voice application that listens for spoken commands and converts them to text by using Azure Speech in Foundry Tools.  
  
How should you complete the Python code?', '[]'::jsonb, ARRAY[]::text[], '`recognize_once()` thực hiện nhận dạng giọng nói đồng bộ cho một câu nói và trả về kết quả văn bản được nhận dạng. Nó phù hợp cho một lệnh nói duy nhất; nhận dạng liên tục mang lại âm thanh dài hơn, đa ngôn ngữ.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-10', 'ai-901', 10, 'Question 10', '[]'::jsonb, ARRAY[]::text[], 'Mô hình GPT hỗ trợ tầm nhìn được triển khai hiển thị điểm cuối suy luận mà ứng dụng gọi để gửi yêu cầu và nhận phản hồi.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-11', 'ai-901', 11, 'You have a Microsoft Foundry project named project1 that contains an Azure OpenAI resource named Resource1.  
  
A gpt-4.1-mini model is deployed to Resource1 by using the model deployment named my-mini-gpt.  
  
You need to connect to my-mini-gpt from an application.  
  
How should you complete the Python code? Each value may be used once, more than once, or not at all.', '{"statements":[{"id":"resource","text":"Slot 1:","correctAnswer":"D"},{"id":"model","text":"Slot 2:","correctAnswer":"B"}],"choices":[{"key":"A","text":"gpt-4.1-mini"},{"key":"B","text":"my-mini-gpt"},{"key":"C","text":"project1"},{"key":"D","text":"resource1"}]}'::jsonb, ARRAY['resource=D', 'model=B']::text[], 'Đối với Azure OpenAI v1, URL cơ sở máy khách là điểm cuối tài nguyên Azure OpenAI, có máy chủ bắt đầu bằng tên tài nguyên. Yêu cầu chỉ định tên triển khai của mô hình đã triển khai trong `model`; `my-mini-gpt` là mô hình triển khai, trong khi `gpt-4.1-mini` là mô hình cơ bản.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-12', 'ai-901', 12, 'You have a Microsoft Foundry project with a generative AI model deployment.  
  
You need to ensure that responses generated by the model minimize costs and stay within a defined length.  
  
Which parameter should you configure?', '[{"key":"A","text":"Top P"},{"key":"B","text":"Temperature"},{"key":"C","text":"Max Completion Tokens"},{"key":"D","text":"Model version settings"}]'::jsonb, ARRAY['C']::text[], 'Mã thông báo hoàn thành tối đa đặt giới hạn trên cho các mã thông báo được tạo để hoàn thành, bao gồm đầu ra hiển thị và mã thông báo lý luận. Việc giới hạn mã thông báo được tạo sẽ hạn chế độ dài phản hồi và giúp kiểm soát chi phí tạo dựa trên mã thông báo.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-13', 'ai-901', 13, 'You have a Microsoft Foundry project that includes a vision-enabled model deployment.  
  
You need to build an application that sends a message containing text and an image URL. The solution must provide the fastest response time.  
  
Which message structure should you include in the request?', '[{"key":"A","text":"a system message that includes both a text item and an image item in the content array"},{"key":"B","text":"a system message that includes only a text item and sends an image item in a separate request"},{"key":"C","text":"a user message that includes only a text item and sends an image item in a separate request"},{"key":"D","text":"a user message that includes both a text item and an image item in the content array"}]'::jsonb, ARRAY['D']::text[], 'Yêu cầu trò chuyện hỗ trợ tầm nhìn có thể đặt văn bản và URL hình ảnh cùng nhau dưới dạng các mục nội dung được nhập trong mảng nội dung của tin nhắn người dùng. Việc kết hợp chúng trong một yêu cầu sẽ tránh được hành trình khứ hồi bổ sung cần thiết khi hình ảnh được gửi riêng, giảm thiểu thời gian phản hồi. Thông báo hệ thống cung cấp hướng dẫn về mô hình; đầu vào văn bản và hình ảnh thuộc về tin nhắn của người dùng.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-14', 'ai-901', 14, 'For each statement, select **Yes** when it is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"An AI generative model is retrained before performing each user request.","correctAnswer":"No"},{"id":"2","text":"An AI agent responds by copying and pasting answers stored in a database.","correctAnswer":"No"},{"id":"3","text":"An AI agent uses a generative AI model to establish actions based on user input.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:No', '2:No', '3:Yes']::text[], 'Các mô hình tổng quát được đào tạo trước và sau đó thực hiện suy luận theo yêu cầu của người dùng; họ không được đào tạo lại theo yêu cầu. Chỉ truy xuất văn bản cơ sở dữ liệu cố định không phải là hành vi của tác nhân. Tác nhân AI có thể sử dụng mô hình AI tổng quát để diễn giải đầu vào và chọn hoặc thực hiện các hành động thích hợp.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-15', 'ai-901', 15, 'For each statement below, select **Yes** if it is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"Voice Live returns only transcribed text.","correctAnswer":"No"},{"id":"2","text":"Voice Live requires you to separately implement speech to text and text to speech services.","correctAnswer":"No"},{"id":"3","text":"Voice Live combines speech to text, reasoning, and text to speech into a single conversational experience.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:No', '2:No', '3:Yes']::text[], 'Azure AI Voice Live là API hội thoại bằng giọng nói theo thời gian thực tích hợp kết hợp nhận dạng giọng nói, lý luận AI tổng quát và tổng hợp giọng nói. Do đó, nó không chỉ đơn thuần là phiên âm và tránh kết nối riêng biệt các dịch vụ chuyển giọng nói thành văn bản và chuyển văn bản thành giọng nói.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-16', 'ai-901', 16, 'For each statement below, select **Yes** if it is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"Human-in-the-loop practices provide accountability for AI-generated decisions.","correctAnswer":"Yes"},{"id":"2","text":"Deploying an AI system to a production environment eliminates the need for ongoing monitoring.","correctAnswer":"No"},{"id":"3","text":"Disclosing the team that designed and deployed an AI system provides accountability for the system''s output.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:No', '3:Yes']::text[], 'Sự giám sát của con người hỗ trợ trách nhiệm giải trình đối với các quyết định do AI tạo ra. AI có trách nhiệm vẫn là trách nhiệm vận hành liên tục sau khi triển khai, bao gồm giám sát hiệu suất, sai lệch và các rủi ro mới nổi. Quyền sở hữu rõ ràng của nhóm thiết kế và triển khai hệ thống AI sẽ thiết lập trách nhiệm giải trình cho kết quả đầu ra của nó.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-17', 'ai-901', 17, 'You have a Microsoft Foundry project that includes a generative AI model deployment.  
  
You test the model by using the Foundry playground.  
  
You need to build an application that submits requests to the deployed model.  
  
Which information must the application include to call the model?', '[{"key":"A","text":"The exported playground session history"},{"key":"B","text":"The model training dataset"},{"key":"C","text":"The Foundry project display name"},{"key":"D","text":"The model endpoint and authentication credentials"}]'::jsonb, ARRAY['D']::text[], 'Ứng dụng gọi mô hình đã triển khai bằng cách gửi yêu cầu suy luận đã được xác thực đến điểm cuối của quá trình triển khai. Thông tin xác thực cho phép yêu cầu đó; lịch sử sân chơi, dữ liệu đào tạo và tên hiển thị của dự án không cung cấp mục tiêu và ủy quyền yêu cầu.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-18', 'ai-901', 18, 'Select the answer that correctly finishes the sentence.', '[]'::jsonb, ARRAY[]::text[], 'Trách nhiệm giải trình có nghĩa là mọi người và tổ chức vẫn chịu trách nhiệm về hệ thống AI và kết quả của chúng, bao gồm cả sự giám sát phù hợp của con người đối với các quyết định do AI tạo ra.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-19', 'ai-901', 19, 'Your company stores thousands of recorded customer-support calls in multiple languages as audio files in Azure Storage.  
  
You need to create text transcripts for all of the recordings.  
  
Which Azure Speech in Foundry Tools capability should you use?', '[{"key":"A","text":"speech to text batch transcription"},{"key":"B","text":"speech to text real-time transcription"},{"key":"C","text":"text to speech"},{"key":"D","text":"speech translation"}]'::jsonb, ARRAY['A']::text[], 'Phiên âm hàng loạt lời nói thành văn bản dành cho khối lượng lớn dữ liệu âm thanh được lưu trữ trong bộ lưu trữ. Nó có thể xử lý nhiều tệp hoặc vùng chứa Azure Blob Storage, giúp nó phù hợp với hàng nghìn cuộc gọi được ghi lại trước đó.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-20', 'ai-901', 20, 'You need to create an AI agent in Microsoft Foundry that adheres to a specific role and behavior when responding to users.  
  
What should you configure?', '[{"key":"A","text":"system instructions"},{"key":"B","text":"temperature"},{"key":"C","text":"tokens per minute (TPM)"},{"key":"D","text":"max completion tokens"}]'::jsonb, ARRAY['A']::text[], 'Hướng dẫn hệ thống xác định mục tiêu, ràng buộc, vai trò và hành vi dự kiến ​​của tác nhân AI. Nhiệt độ kiểm soát tính ngẫu nhiên của đầu ra, mã thông báo mỗi phút là giới hạn công suất và mã thông báo hoàn thành tối đa kiểm soát độ dài phản hồi tối đa. Microsoft Foundry xác định hướng dẫn là thành phần xác định mục tiêu, ràng buộc và hành vi của tác nhân.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-21', 'ai-901', 21, 'You are building an application that converts text to spoken audio and stores the synthesized audio in a file by using Azure Speech in Foundry Tools.  
  
How should you complete the Python code?', '[]'::jsonb, ARRAY[]::text[], '`AudioOutputConfig(filename="output.wav")` định cấu hình đầu ra tổng hợp Speech SDK để ghi vào tệp âm thanh được chỉ định. Luồng đầu ra yêu cầu đối tượng luồng, trong khi `AudioStreamFormat` chỉ mô tả định dạng luồng.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-22', 'ai-901', 22, 'You need to compare the costs of large language models (LLMs) for a generative AI solution.  
  
What should you use in the Microsoft Foundry portal?', '[{"key":"A","text":"Compliance"},{"key":"B","text":"Evaluator catalog"},{"key":"C","text":"Tools"},{"key":"D","text":"Model leaderboard"}]'::jsonb, ARRAY['D']::text[], 'Bảng xếp hạng Mô hình so sánh các mô hình theo chi phí ước tính, cùng với chất lượng, độ an toàn và thông lượng. Nó hỗ trợ so sánh chi phí chuẩn và so sánh song song các LLM để lựa chọn mô hình.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-23', 'ai-901', 23, 'You have an Azure subscription.  
  
You need to use Azure Content Understanding in Foundry Tools to extract structured information from invoices.  
  
What should you provision?', '[{"key":"A","text":"A Microsoft Foundry project"},{"key":"B","text":"an Azure OpenAI resource"},{"key":"C","text":"a Microsoft Foundry resource"},{"key":"D","text":"an Azure AI Search service"}]'::jsonb, ARRAY['C']::text[], 'Hiểu nội dung Azure trong Công cụ đúc có sẵn thông qua tài nguyên Microsoft Foundry và có thể trích xuất dữ liệu có cấu trúc do lược đồ xác định từ các tài liệu như hóa đơn.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-24', 'ai-901', 24, 'You have a Microsoft Foundry project that includes a vision-enabled chat model deployment.  
  
You are developing a Python application that sends a request with a user prompt and a local JPEG image.  
  
You need to include the image as binary data in the request. What should the `image_url.ur1` field be set to?', '[{"key":"A","text":"data:image/jpeg;base64,<binary_image_data>"},{"key":"B","text":"file:///C:/images/photo.jpg"},{"key":"C","text":"C:\\images\\photo.jpg"},{"key":"D","text":"https://<your-storage-account>.blob.core.windows.net/<container>/<file>.jpg"}]'::jsonb, ARRAY['A']::text[], 'JPEG cục bộ phải được mã hóa dưới dạng Base64 và được cung cấp dưới dạng URL dữ liệu bằng tiền tố `data:image/jpeg;base64,`. Điều này nhúng dữ liệu hình ảnh trực tiếp vào tải trọng yêu cầu; đường dẫn tệp cục bộ không phải là URL có thể truy cập dịch vụ.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-25', 'ai-901', 25, 'You are using the Azure Speech SDK to create a Python application that supports real-time spoken conversations.  
  
Which Azure Speech class should be used to configure the connection to the Azure Speech service?', '[{"key":"A","text":"AudioOutputConfig"},{"key":"B","text":"SpeechSynthesizer"},{"key":"C","text":"AudioConfig"},{"key":"D","text":"SpeechConfig"}]'::jsonb, ARRAY['D']::text[], '`SpeechConfig` định cấu hình quyền truy cập vào dịch vụ Azure Speech bằng cách cung cấp chi tiết kết nối và xác thực như khóa đăng ký cùng với khu vực hoặc điểm cuối. `AudioConfig` và `AudioOutputConfig` định cấu hình nguồn hoặc đích âm thanh và `SpeechSynthesizer` sử dụng cấu hình dịch vụ để tổng hợp giọng nói.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-26', 'ai-901', 26, 'Question 26', '[]'::jsonb, ARRAY[]::text[], 'Nguyên tắc minh bạch của Microsoft là mọi người phải hiểu được hệ thống AI làm gì và tại sao. Bảo vệ dữ liệu nhạy cảm là quyền riêng tư và bảo mật, giảm thiểu sự thiên vị là sự công bằng và sự giám sát của con người là trách nhiệm giải trình.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-27', 'ai-901', 27, 'For each statement below, select **Yes** when it is true; otherwise, select **No**.', '{"statements":[{"id":"1","text":"Azure Content Understanding in Foundry Tools can analyze only PDF documents.","correctAnswer":"No"},{"id":"2","text":"Azure Content Understanding in Foundry Tools results are returned in the JSON format.","correctAnswer":"Yes"},{"id":"3","text":"Azure Content Understanding in Foundry Tools can extract structured fields from documents and forms by using optical character recognition (OCR) to read text.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:No', '2:Yes', '3:Yes']::text[], 'Hiểu nội dung chấp nhận các tệp PDF cũng như hình ảnh, tài liệu Office, văn bản, email và các định dạng được hỗ trợ khác, do đó, nó không giới hạn ở các tệp PDF. API của nó trả về kết quả phân tích JSON có cấu trúc. Nó hỗ trợ trích xuất văn bản dựa trên OCR cho các tài liệu dựa trên hình ảnh và có thể trả về các trường có cấu trúc phù hợp với lược đồ.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-28', 'ai-901', 28, 'You have a Microsoft Foundry project that includes an agent named Agent1.  
  
You need to ensure that Agent1 always invokes an Azure function when it responds to user input.  
  
What should you set `tool_choice` to for Agent1?', '[{"key":"A","text":"required"},{"key":"B","text":"auto"},{"key":"C","text":"none"}]'::jsonb, ARRAY['A']::text[], 'Việc đặt `tool_choice` thành `required` yêu cầu mô hình gọi một hoặc nhiều công cụ đã định cấu hình. `auto` cho phép mô hình trả lời mà không cần gọi công cụ và `none` ngăn các cuộc gọi công cụ. [Microsoft Foundry Agent Service tool best practices](https://learn.microsoft.com/en-us/azure/foundry/agents/concepts/tool-best-practice)', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-29', 'ai-901', 29, 'For each statement, select **Yes** when it is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"Generating a response to a user prompt occurs during the inference stage.","correctAnswer":"Yes"},{"id":"2","text":"A generative AI model generates responses by copying stored documents directly from the model’s training data.","correctAnswer":"No"},{"id":"3","text":"A generative AI model produces output by predicting the next token based on patterns learned from the model’s training data.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:No', '3:Yes']::text[], 'Suy luận sử dụng một mô hình đã được đào tạo để tạo ra phản hồi cho lời nhắc. Dữ liệu huấn luyện được sử dụng để tìm hiểu các tham số mô hình thay vì được lưu trữ dưới dạng tài liệu nguồn để sao chép trực tiếp. Các mô hình ngôn ngữ tạo sinh tự hồi quy tạo ra văn bản từng mã thông báo một bằng cách dự đoán mã thông báo tiếp theo từ các mẫu thống kê đã học.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-30', 'ai-901', 30, 'Question 30', '[]'::jsonb, ARRAY[]::text[], 'Hiểu nội dung Azure AI sử dụng quy trình phân tích không đồng bộ: gửi nội dung, sau đó truy xuất kết quả hoạt động đã hoàn thành. Nó hỗ trợ nhiều hơn OCR và trả về thông tin được trích xuất và suy luận có cấu trúc.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-31', 'ai-901', 31, 'For each of the following statements, select **Yes** if the statement is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"In the new Microsoft Foundry portal, you must fine-tune a model before you can deploy the model.","correctAnswer":"No"},{"id":"2","text":"In the new Microsoft Foundry portal, you can test a model from the model catalog only after you deploy the model.","correctAnswer":"Yes"},{"id":"3","text":"In the new Microsoft Foundry portal, you can deploy a model from the model catalog only after retraining the model.","correctAnswer":"No"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:No', '2:Yes', '3:No']::text[], 'Danh mục mô hình hỗ trợ triển khai trực tiếp các mô hình có sẵn; fine-tuning và đào tạo lại là các quy trình tùy chỉnh tùy chọn, không phải là điều kiện tiên quyết để triển khai. Một mô hình phải được triển khai đến điểm cuối trước khi có thể thử nghiệm nó trong sân chơi.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-32', 'ai-901', 32, 'You have a Microsoft Foundry project containing a model deployment.  
  
You are developing an application that sends an image and a user question to the model. You need to send text and image content in the same request so that the model can return an answer.  
  
Complete the Python code. Values may be used once, more than once, or not at all.', '{"statements":[{"id":"content_text_type","text":"Slot 1:","correctAnswer":"B"},{"id":"content_image_type","text":"Slot 2:","correctAnswer":"A"}],"choices":[{"key":"A","text":"input_image"},{"key":"B","text":"input_text"},{"key":"C","text":"input_url"},{"key":"D","text":"output_image"},{"key":"E","text":"output_text"}]}'::jsonb, ARRAY['content_text_type=B', 'content_image_type=A']::text[], 'API phản hồi chấp nhận đầu vào của người dùng đa phương thức dưới dạng danh sách `content`. Lời nhắc văn bản sử dụng `{"type": "input_text", "text":.}`, trong khi URL hình ảnh sử dụng `{"type": "input_image", "image_url":.}`. `output_text` được API trả về và không phải là loại nội dung đầu vào.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-33', 'ai-901', 33, 'Question 33', '[]'::jsonb, ARRAY[]::text[], 'OCR phát hiện và trích xuất văn bản từ hình ảnh và tài liệu được quét, đây là một nhiệm vụ thị giác máy tính.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-34', 'ai-901', 34, 'For each statement, select **Yes** when it is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"The Temperature parameter can be set before deploying a model.","correctAnswer":"No"},{"id":"2","text":"During inference, the model name is used to route requests to a specific deployment.","correctAnswer":"No"},{"id":"3","text":"After a model is deployed, both code and testing tools can be used to interact with the model.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:No', '2:No', '3:Yes']::text[], 'Nhiệt độ kiểm soát việc tạo tại thời điểm suy luận và được cung cấp theo yêu cầu. Azure OpenAI định tuyến các yêu cầu đến triển khai được đặt tên, không trực tiếp đến tên mô hình. Một mô hình đã triển khai có thể được thực hiện trong sân chơi và được gọi theo chương trình thông qua API hoặc SDK REST.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-35', 'ai-901', 35, 'For each of the following statements, select Yes if the statement is true. Otherwise, select No.', '{"statements":[{"id":"1","text":"Evaluators in Microsoft Foundry replace the need for configuring token limits.","correctAnswer":"No"},{"id":"2","text":"Evaluators in Microsoft Foundry can assess the quality and safety of responses generated by a generative AI model.","correctAnswer":"Yes"},{"id":"3","text":"Evaluators in Microsoft Foundry can retrain a deployed generative AI model automatically when quality issues are detected.","correctAnswer":"No"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:No', '2:Yes', '3:No']::text[], 'Trình đánh giá Microsoft Foundry đo lường các phản hồi được tạo ra đối với các rủi ro về chất lượng và an toàn; chúng không thay thế cấu hình giới hạn mã thông báo. Đánh giá tạo ra các phép đo và kết quả chứ không phải tự động đào tạo lại các mô hình đã triển khai.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-36', 'ai-901', 36, 'You are building an application that processes voicemail recordings by using Azure Content Understanding in Foundry Tools.  
  
Which Azure Content Understanding feature converts audio into text?', '[{"key":"A","text":"key phrase extraction"},{"key":"B","text":"transcription"},{"key":"C","text":"Voice Live"},{"key":"D","text":"optical character recognition (OCR)"}]'::jsonb, ARRAY['B']::text[], 'Bộ phân tích âm thanh Hiểu nội dung Azure sử dụng phiên âm để chuyển đổi âm thanh hội thoại thành bản ghi dựa trên văn bản có thể tìm kiếm và phân tích được. Trích xuất cụm từ khóa phân tích văn bản hiện có, OCR trích xuất văn bản từ nội dung trực quan và Voice Live không phải là tính năng chuyển đổi âm thanh thành văn bản.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-37', 'ai-901', 37, 'You need to create an AI solution that produces marketing email drafts from a brief description of a product and its intended audience.  
  
Which AI workload should you use?', '[{"key":"A","text":"speech recognition"},{"key":"B","text":"text classification"},{"key":"C","text":"generative AI"},{"key":"D","text":"computer vision"}]'::jsonb, ARRAY['C']::text[], 'AI sáng tạo tạo ra nội dung mới, bao gồm văn bản email tiếp thị phù hợp, từ các lời nhắc mô tả sản phẩm và đối tượng mục tiêu của sản phẩm đó.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-38', 'ai-901', 38, 'You are building an AI-powered customer support application.  
  
Which task exemplifies the Microsoft responsible AI principle of inclusiveness?', '[{"key":"A","text":"Encrypt stored customer data and restrict access by using role-based controls."},{"key":"B","text":"Evaluate model outputs across demographic groups to reduce bias."},{"key":"C","text":"Design the interface to support multiple languages and screen readers."},{"key":"D","text":"Provide explanations about how predictions are generated."}]'::jsonb, ARRAY['C']::text[], 'Tính toàn diện đòi hỏi phải thiết kế các hệ thống mà những người có ngôn ngữ, khả năng và nhu cầu đa dạng có thể truy cập và sử dụng. Hỗ trợ nhiều ngôn ngữ và trình đọc màn hình giúp giao diện dễ tiếp cận hơn với nhiều người dùng hơn.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-39', 'ai-901', 39, 'You are building an application that uses Azure Content Understanding in Foundry Tools to extract structured information from several content types.  
  
You need to extract scanned invoices in PDF format and voicemail recordings in WAV format.  
  
Which analyzer type should be used for each content type? Each analyzer type can be used once, multiple times, or not at all.', '{"statements":[{"id":"scanned_invoices","text":"Scanned invoices:","correctAnswer":"B"},{"id":"voicemail_recordings","text":"Voicemail recordings:","correctAnswer":"A"}],"choices":[{"key":"A","text":"audio analyzer"},{"key":"B","text":"document analyzer"},{"key":"C","text":"image analyzer"},{"key":"D","text":"video analyzer"}]}'::jsonb, ARRAY['scanned_invoices=B', 'voicemail_recordings=A']::text[], 'Máy phân tích tài liệu trích xuất thông tin có cấu trúc từ nội dung tài liệu, bao gồm các tệp PDF như hóa đơn được quét. Máy phân tích âm thanh xử lý nội dung âm thanh, bao gồm các tệp WAV chẳng hạn như bản ghi thư thoại.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-40', 'ai-901', 40, 'For each of the following statements, select **Yes** if it is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"Fairness can be achieved by focusing solely on improving the overall accuracy of an AI model.","correctAnswer":"No"},{"id":"2","text":"Evaluating AI system outputs to identify and reduce bias across demographic groups supports fairness.","correctAnswer":"Yes"},{"id":"3","text":"Ensuring fairness for an AI system means that all users always receive the same output from the system.","correctAnswer":"No"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:No', '2:Yes', '3:No']::text[], 'Chỉ riêng độ chính xác tổng thể có thể che giấu hiệu suất không đồng đều hoặc sự chênh lệch có hại giữa các nhóm nhân khẩu học, do đó, độ chính xác tổng thể là không đủ để đảm bảo sự công bằng. Đánh giá kết quả đầu ra theo nhóm nhân khẩu học giúp xác định và giảm bớt sự thiên vị. Công bằng liên quan đến việc đối xử công bằng và kết quả theo một định nghĩa công bằng phù hợp; nó không yêu cầu mọi người dùng đều nhận được đầu ra giống hệt nhau.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-41', 'ai-901', 41, 'You are building a web app that processes invoices to calculate expenses.  
  
You need to extract structured fields, including nested values, from the invoices by using a defined schema.  
  
What should you use?', '[{"key":"A","text":"an optical character recognition (OCR)-only document processing pipeline"},{"key":"B","text":"a transcription workflow in Azure Speech in Foundry Tools"},{"key":"C","text":"an analyzer in Azure Content Understanding in Foundry Tools"},{"key":"D","text":"an Azure AI Search service"}]'::jsonb, ARRAY['C']::text[], 'Trình phân tích trong phần Hiểu nội dung Azure trong Công cụ đúc sẽ xác định lược đồ trường để trích xuất dữ liệu tài liệu có cấu trúc. Lược đồ của nó hỗ trợ các trường mảng và đối tượng lồng nhau, chứa các chi tiết hóa đơn như chi tiết đơn hàng và các giá trị liên quan của chúng.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-42', 'ai-901', 42, 'You are developing an application that analyzes invoices by using Azure Content Understanding in Foundry Tools.  
  
You need to ensure that the application retrieves the analysis results after processing is complete. How should you complete the Python code?', '[]'::jsonb, ARRAY[]::text[], '`begin_analyze` trả về một trình thăm dò hoạt động lâu dài của Azure. Gọi `poller.result()` chờ hoàn thành khi cần và trả về kết quả phân tích đã hoàn thành.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-43', 'ai-901', 43, 'A company processes customer-support emails.  
  
An AI solution must automatically recognize mentions of people, organizations, and locations in those emails. Which text-analysis technique should be used?', '[{"key":"A","text":"Named Entity Recognition (NER)"},{"key":"B","text":"key phrase extraction"},{"key":"C","text":"sentiment analysis"},{"key":"D","text":"summarization"}]'::jsonb, ARRAY['A']::text[], 'Nhận dạng thực thể được đặt tên (NER) phát hiện các thực thể được đặt tên trong văn bản phi cấu trúc và phân loại chúng thành các loại như cá nhân, tổ chức và vị trí.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-44', 'ai-901', 44, 'Question 44', '[]'::jsonb, ARRAY[]::text[], 'Sự công bằng đòi hỏi phải xác định và giảm thiểu sự thiên vị để hệ thống AI không tạo ra những kết quả khác nhau một cách vô lý cho các nhóm nhân khẩu học.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-45', 'ai-901', 45, 'Question 45', '[]'::jsonb, ARRAY[]::text[], 'Đầu vào hình ảnh API phản hồi hỗ trợ URL hình ảnh, bao gồm dữ liệu hình ảnh được mã hóa base64 được cung cấp dưới dạng URL dữ liệu. Tệp đính kèm CSV, luồng MP4 và mã thông báo SAS không phải là định dạng dữ liệu hình ảnh cho đầu vào này.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-46', 'ai-901', 46, 'You have a Microsoft Foundry project that includes a vision-enabled model deployment.  
  
You are developing an application that sends images to the model. You need to ensure the model can analyze those images.  
  
In which two formats can you supply the images? Each correct answer presents part of the solution.  
  
**NOTE:** Each correct selection is worth one point.', '[{"key":"A","text":"a base64-encoded image data string"},{"key":"B","text":"a JSON document that describes the image content"},{"key":"C","text":"a UTF-8 encoded text description of the image"},{"key":"D","text":"a publicly accessible URL of the image"}]'::jsonb, ARRAY['A', 'D']::text[], 'Đầu vào mô hình hỗ trợ tầm nhìn hỗ trợ tham chiếu hình ảnh bằng cách sử dụng URL có thể truy cập công khai và chuỗi dữ liệu hình ảnh được mã hóa Base64 được nhúng. Các định dạng này cung cấp tài nguyên hình ảnh thực tế hoặc byte hình ảnh cần thiết để phân tích trực quan.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-47', 'ai-901', 47, 'You need to build an AI solution that creates new product images from written descriptions supplied by users.  
  
Which AI workload should you use?', '[{"key":"A","text":"image analysis"},{"key":"B","text":"image generation"},{"key":"C","text":"object detection"},{"key":"D","text":"optical character recognition (OCR)"}]'::jsonb, ARRAY['B']::text[], 'Khối lượng công việc tạo hình ảnh tạo ra hình ảnh mới từ lời nhắc hoặc mô tả bằng văn bản. Phân tích hình ảnh diễn giải các hình ảnh hiện có, phát hiện đối tượng xác định các đối tượng bên trong chúng và OCR trích xuất văn bản từ hình ảnh.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-48', 'ai-901', 48, 'Question 48', '[]'::jsonb, ARRAY[]::text[], 'Azure Content Hiểu sử dụng lược đồ phân tích để chỉ định các trường có cấu trúc cần được trích xuất từ ​​nội dung. Quá trình xử lý chỉ OCR tạo ra văn bản, trong khi danh sách từ khóa và hành vi API đồng bộ không xác định lược đồ trích xuất.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-49', 'ai-901', 49, 'Question 49', '[]'::jsonb, ARRAY[]::text[], 'Danh mục mô hình của Microsoft Foundry cho phép các nhà phát triển khám phá, so sánh và triển khai nhiều lựa chọn mô hình AI tổng hợp.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-50', 'ai-901', 50, 'Question 50', '[]'::jsonb, ARRAY[]::text[], 'Lời nhắc hệ thống cung cấp các hướng dẫn xác định vai trò, hành vi dự kiến ​​và các ràng buộc vận hành của tác nhân AI. Các vị trí triển khai quản lý môi trường triển khai ứng dụng, nhúng các chỉ mục hỗ trợ truy xuất và các công việc fine-tuning tùy chỉnh mô hình thông qua dữ liệu đào tạo thay vì xác định hướng dẫn thời gian chạy của một tác nhân riêng lẻ.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-51', 'ai-901', 51, 'For each statement below, select **Yes** if it is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"In Microsoft Foundry Agent Service, setting tool_choice to auto for an agent enables the agent to decide whether to call a tool.","correctAnswer":"Yes"},{"id":"2","text":"In Microsoft Foundry Agent Service, setting tool_choice to none for an agent means that the model decides whether to call a tool.","correctAnswer":"No"},{"id":"3","text":"In Microsoft Foundry Agent Service, setting tool_choice to required for an agent ensures that the agent must call one or more tools during each run.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:No', '3:Yes']::text[], '`tool_choice: auto` cho phép mô hình quyết định có nên gọi một công cụ hay không. `tool_choice: none` ngăn việc gọi công cụ thay vì để mô hình quyết định. `tool_choice: required` yêu cầu một hoặc nhiều lệnh gọi công cụ.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-52', 'ai-901', 52, 'You are building an application that extracts fields from PDFs by using Azure Content Understanding in Foundry Tools.  
  
You need to use the Python SDK to submit a PDF for analysis and retrieve the extraction results.  
  
What should you do?', '[{"key":"A","text":"Call analyze() to return the extracted fields synchronously in the same request."},{"key":"B","text":"Submit the PDF to an analyzer and read the results from the request headers."},{"key":"C","text":"Call begin_analyze(), and then call poller.result() to retrieve the results."},{"key":"D","text":"Use optical character recognition (OCR) to extract text from the PDF and map the fields in the code."}]'::jsonb, ARRAY['C']::text[], 'Phân tích Hiểu nội dung Azure sử dụng một hoạt động dài hạn. `begin_analyze()` của Python SDK bắt đầu phân tích và trả về một trình thăm dò, đồng thời `poller.result()` đợi thao tác kết thúc và trả về `AnalysisResult` có cấu trúc chứa các trường được trích xuất.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-53', 'ai-901', 53, 'Question 53', '[]'::jsonb, ARRAY[]::text[], 'Xử lý ngôn ngữ tự nhiên cho phép các ứng dụng diễn giải và trả lời các câu hỏi do người dùng viết. Thị giác máy tính xử lý nội dung trực quan, đồng thời dự báo dự đoán kết quả trong tương lai từ dữ liệu.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-54', 'ai-901', 54, 'Question 54', '[]'::jsonb, ARRAY[]::text[], 'Nguyên tắc về độ tin cậy và an toàn của Microsoft yêu cầu các hệ thống AI phải hoạt động đáng tin cậy, an toàn và nhất quán trong các điều kiện dự kiến. Sự giám sát của con người gắn liền với trách nhiệm giải trình, kết quả công bằng với sự công bằng và giải thích rõ ràng với tính minh bạch.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-55', 'ai-901', 55, 'For each of the following statements, select **Yes** if it is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"Image analysis capabilities in Microsoft Foundry Tools can perform optical character recognition (OCR).","correctAnswer":"Yes"},{"id":"2","text":"Image analysis capabilities in Microsoft Foundry Tools can generate captions and descriptive tags for images.","correctAnswer":"Yes"},{"id":"3","text":"Image analysis capabilities in Microsoft Foundry Tools are designed primarily to create new images from text prompts.","correctAnswer":"No"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:Yes', '3:No']::text[], 'Microsoft Foundry Công cụ phân tích hình ảnh cung cấp OCR và có thể phân tích hình ảnh để tạo chú thích và thẻ. Nó phân tích các hình ảnh hiện có; tạo hình ảnh từ lời nhắc văn bản là một khả năng tạo hình ảnh riêng biệt.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-56', 'ai-901', 56, 'You are building an application that captures a user’s voice and sends the recorded audio to a deployed multimodal model in Microsoft Foundry.  
  
You need to send the user’s request to the model.  
  
What should the request include?', '[{"key":"A","text":"an image of the audio frames"},{"key":"B","text":"a text transcript of the voice"},{"key":"C","text":"an audio input prompt"},{"key":"D","text":"a text embedding vector"}]'::jsonb, ARRAY['C']::text[], 'Các mô hình đa phương thức hỗ trợ âm thanh chấp nhận âm thanh đã ghi dưới dạng lời nhắc đầu vào âm thanh, cho phép mô hình xử lý giọng nói trực tiếp. Bản ghi văn bản chỉ cần thiết nếu ứng dụng thực hiện chuyển đổi giọng nói thành văn bản trước tiên.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-57', 'ai-901', 57, 'For each of the following statements, select **Yes** if the statement is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"Using Azure Speech in Foundry Tools for batch transcription requires live audio input from a microphone.","correctAnswer":"No"},{"id":"2","text":"Azure Speech in Foundry Tools can analyze video frames to detect and label objects while transcribing audio.","correctAnswer":"No"},{"id":"3","text":"Speech translation in Azure Speech in Foundry Tools only supports translating speech into spoken output in another language.","correctAnswer":"No"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:No', '2:No', '3:No']::text[], 'Phiên âm hàng loạt được thiết kế cho các tệp âm thanh được ghi trước thay vì đầu vào micrô trực tiếp. Azure Speech không thực hiện các tác vụ thị giác máy tính như phát hiện và gắn nhãn đối tượng trong khung hình video. Dịch giọng nói có thể trả về văn bản đã dịch và cũng có thể tổng hợp giọng nói đã dịch, do đó, đầu ra bằng giọng nói là tùy chọn chứ không phải là kết quả được hỗ trợ duy nhất.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-58', 'ai-901', 58, 'Identifying the source of the data used to train a model is an example of which responsible AI principle?', '[{"key":"A","text":"privacy and security"},{"key":"B","text":"reliability and safety"},{"key":"C","text":"fairness"},{"key":"D","text":"transparency"}]'::jsonb, ARRAY['D']::text[], 'Tính minh bạch yêu cầu mọi người có thể hiểu cách hệ thống AI hoạt động và có thể xác minh nguồn thông tin cũng như cách xử lý dữ liệu của nó. Việc tiết lộ nguồn dữ liệu đào tạo mang lại khả năng hiển thị đó.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-59', 'ai-901', 59, 'For each statement below, select **Yes** when it is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"An agent must be published before it can be used by applications to send requests.","correctAnswer":"Yes"},{"id":"2","text":"In the Microsoft Foundry portal, you must fine-tune the model before you can publish an agent.","correctAnswer":"No"},{"id":"3","text":"In the Microsoft Foundry portal, an agent is published automatically when you save its configuration.","correctAnswer":"No"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:No', '3:No']::text[], 'Việc xuất bản chuyển tác nhân từ dự án phát triển sang Ứng dụng tác nhân sẵn sàng sản xuất mà người tiêu dùng bên ngoài có thể gọi thông qua điểm cuối ổn định. Fine-tuning không bắt buộc phải xuất bản; một tác nhân có thể sử dụng mô hình đã triển khai hiện có. Việc lưu cấu hình sẽ tạo hoặc duy trì phiên bản tác nhân, trong khi xuất bản là một hành động rõ ràng riêng biệt để hiển thị phiên bản đó cho mục đích sử dụng bên ngoài.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-60', 'ai-901', 60, 'Your company gives users clear details about an AI system’s purpose, functionality, and limitations.  
  
Which Microsoft responsible AI principle does this illustrate?', '[{"key":"A","text":"transparency"},{"key":"B","text":"accountability"},{"key":"C","text":"fairness"},{"key":"D","text":"reliability and safety"}]'::jsonb, ARRAY['A']::text[], 'Tính minh bạch yêu cầu truyền đạt rõ ràng mục đích, khả năng và giới hạn của hệ thống AI để mọi người có thể hiểu và sử dụng nó một cách thích hợp.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-61', 'ai-901', 61, 'For each of the following statements, select Yes if the statement is true. Otherwise, select No.', '{"statements":[{"id":"1","text":"You can deploy a supported base model directly from the model catalog.","correctAnswer":"Yes"},{"id":"2","text":"The playground is used to create the model deployment before the model can be tested.","correctAnswer":"No"},{"id":"3","text":"After deploying a model, you can use the playground in the Microsoft Foundry portal to send prompts and review responses.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:No', '3:Yes']::text[], 'Các mô hình cơ sở được hỗ trợ có thể được triển khai từ danh mục mô hình. Sân chơi dùng để tương tác và đánh giá một mô hình đã triển khai bằng cách gửi lời nhắc và xem xét phản hồi của mô hình đó, thay vì để tự tạo quá trình triển khai.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-62', 'ai-901', 62, 'For each statement below, select **Yes** when it is true; otherwise, select **No**.', '{"statements":[{"id":"1","text":"All AI models can analyze and generate images.","correctAnswer":"No"},{"id":"2","text":"A multimodal generative AI model can interpret image input in a prompt.","correctAnswer":"Yes"},{"id":"3","text":"A multimodal model can process prompts that include both text and images.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:No', '2:Yes', '3:Yes']::text[], 'Các mô hình AI không hỗ trợ phổ biến việc phân tích hình ảnh hoặc tạo hình ảnh; những khả năng như vậy đòi hỏi phải có tầm nhìn phù hợp và/hoặc hỗ trợ mô hình tạo hình ảnh. AI tạo đa phương thức có thể diễn giải hình ảnh đầu vào và kết hợp nội dung hình ảnh và văn bản trong một lời nhắc.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-63', 'ai-901', 63, 'Question 63', '[]'::jsonb, ARRAY[]::text[], 'Phiên âm chuyển đổi nội dung giọng nói trong âm thanh và video thành văn bản. Tính năng ghi nhật ký giúp phân biệt người nói, trích xuất cụm từ khóa xác định các thuật ngữ nổi bật và tổng hợp giọng nói chuyển văn bản thành giọng nói.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-64', 'ai-901', 64, 'Question 64', '[]'::jsonb, ARRAY[]::text[], 'Thị giác máy tính phân tích hình ảnh và video để phát hiện, phân loại và đếm các đối tượng, chẳng hạn như động vật xuất hiện trong nguồn cấp dữ liệu video.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-65', 'ai-901', 65, 'For each of the following statements, select Yes if the statement is true. Otherwise, select No.', '{"statements":[{"id":"1","text":"Transparency focuses on increasing system performance and throughput.","correctAnswer":"No"},{"id":"2","text":"Transparency is supported when users are informed about an AI system''s purpose and limitations.","correctAnswer":"Yes"},{"id":"3","text":"Providing meaningful explanations of how an AI system generates its results supports transparency.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:No', '2:Yes', '3:Yes']::text[], 'Tính minh bạch làm cho các hệ thống AI và hành vi của chúng trở nên dễ hiểu đối với các bên liên quan. Nó bao gồm mục đích truyền đạt và các hạn chế cũng như đưa ra những giải thích hữu ích về hành vi của hệ thống; hiệu suất và thông lượng là những mối quan tâm kỹ thuật riêng biệt.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-66', 'ai-901', 66, 'Question 66', '[]'::jsonb, ARRAY[]::text[], 'Thị giác máy tính bao gồm nhận dạng ký tự quang học (OCR), giúp phát hiện và trích xuất văn bản in hoặc viết tay từ hình ảnh. AI sáng tạo tạo ra nội dung mới, trong khi xử lý ngôn ngữ tự nhiên chủ yếu phân tích và tạo ra dữ liệu ngôn ngữ.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-67', 'ai-901', 67, 'Question 67', '[]'::jsonb, ARRAY[]::text[], 'Độ tin cậy và an toàn đòi hỏi hệ thống AI phải hoạt động đáng tin cậy và an toàn trong suốt vòng đời của nó, bao gồm cả việc xử lý các điều kiện dự kiến ​​và bất ngờ một cách thích hợp. Đây là điều cần thiết cho xe tự lái.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-68', 'ai-901', 68, 'You are building a simple application that uses the Microsoft Foundry SDK to send chat prompts to a model.  
  
Which three elements must you supply in the code to run the application? Each correct answer represents part of the solution.  
  
NOTE: Each correct selection is worth one point.', '[{"key":"A","text":"the model deployment name"},{"key":"B","text":"the task type"},{"key":"C","text":"the Foundry project display name"},{"key":"D","text":"Microsoft Entra ID credentials"},{"key":"E","text":"the endpoint URL"}]'::jsonb, ARRAY['A', 'D', 'E']::text[], 'Mã SDK Microsoft Foundry xây dựng `AIProjectClient` với điểm cuối dự án và `DefaultAzureCredential` để xác thực Microsoft Entra ID. Yêu cầu trò chuyện hoặc phản hồi cũng chỉ định tên triển khai mô hình. Tên hiển thị dự án và loại tác vụ không bắt buộc phải nhập cho cấu hình máy khách và lệnh gọi mô hình này.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-69', 'ai-901', 69, 'Which two of the following are types of generative AI models? Each correct answer provides a complete solution.  
  
> **Note:** Each correct answer is worth one point.', '[{"key":"A","text":"computer vision"},{"key":"B","text":"GPT"},{"key":"C","text":"DALL-E"},{"key":"D","text":"transformer"},{"key":"E","text":"natural language processing"}]'::jsonb, ARRAY['B', 'C']::text[], 'GPT là họ mô hình tổng quát để tạo văn bản và DALL-E là họ mô hình tổng quát để tạo hình ảnh. Thị giác máy tính và xử lý ngôn ngữ tự nhiên là các lĩnh vực có khả năng AI và máy biến áp là kiến ​​trúc mạng thần kinh.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-70', 'ai-901', 70, 'You are building an application that uses the Azure Language SDK with a Microsoft Foundry resource.  
  
You need to return a list of key topics from unstructured text.  
  
Which Python method should you use?', '[{"key":"A","text":"client.begin_extract_summary()"},{"key":"B","text":"client.extract_key_phrases()"},{"key":"C","text":"client.recognize_linked_entities()"},{"key":"D","text":"client.recognize_entities()"}]'::jsonb, ARRAY['B']::text[], 'Trích xuất cụm từ khóa Ngôn ngữ Azure xác định các khái niệm chính trong văn bản phi cấu trúc. Phương thức máy khách Phân tích văn bản Python `extract_key_phrases()` trả về các cụm từ khóa đó.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-71', 'ai-901', 71, 'Question 71', '[]'::jsonb, ARRAY[]::text[], 'Các mô hình đa phương thức có thể chấp nhận đầu vào hình ảnh cùng với lời nhắc bằng văn bản. Mô hình nhúng tạo ra biểu diễn vectơ, mô hình chuyển giọng nói thành văn bản phiên âm âm thanh và mô hình chỉ văn bản không chấp nhận đầu vào hình ảnh.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-72', 'ai-901', 72, 'Question 72', '[]'::jsonb, ARRAY[]::text[], 'Ngôn ngữ Azure trong Công cụ đúc cung cấp khả năng phân tích văn bản cho các tổng đài viên thông qua máy chủ MCP Ngôn ngữ Azure. Tác nhân cũng cần có kết nối Foundry được định cấu hình để xác thực với điểm cuối Ngôn ngữ Azure.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-73', 'ai-901', 73, 'Which of the Microsoft responsible AI principles is exemplified by transparency?', '[{"key":"A","text":"ensuring that developers are accountable for the solutions they create"},{"key":"B","text":"ensuring that opportunities are allocated equally to all applicants"},{"key":"C","text":"helping users understand the decisions made by an AI system"},{"key":"D","text":"ensuring that the privileged data of users is stored in a secure manner"}]'::jsonb, ARRAY['C']::text[], 'Tính minh bạch cho phép mọi người hiểu hệ thống AI làm gì, tại sao nó hoạt động như vậy và cách nó đưa ra quyết định.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-74', 'ai-901', 74, 'For each of the following statements, select Yes if the statement is true. Otherwise, select No.', '{"statements":[{"id":"1","text":"Limiting access to AI systems and data reduces the risk of unauthorized data exposure.","correctAnswer":"Yes"},{"id":"2","text":"Sharing personal user data improves collaboration and supports responsible AI practices.","correctAnswer":"No"},{"id":"3","text":"Protecting personal data and complying with data regulations are key considerations in responsible AI.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:No', '3:Yes']::text[], 'Kiểm soát truy cập làm giảm nguy cơ lộ dữ liệu trái phép. Dữ liệu cá nhân chỉ nên được chia sẻ khi hợp lý và được bảo vệ, không chỉ để cải thiện sự hợp tác. AI có trách nhiệm bao gồm bảo vệ dữ liệu cá nhân và tuân thủ các yêu cầu hiện hành về quyền riêng tư và bảo vệ dữ liệu.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-75', 'ai-901', 75, 'Question 75', '[]'::jsonb, ARRAY[]::text[], 'Nhận dạng thực thể được đặt tên (NER) phát hiện các thực thể được đặt tên trong văn bản, bao gồm vị trí, ngày tháng và số lượng. Trích xuất cụm từ khóa tìm thấy các cụm từ quan trọng, phát hiện ngôn ngữ xác định ngôn ngữ của văn bản và phân tích cảm xúc xác định sự phân cực của quan điểm.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-76', 'ai-901', 76, 'You are building an application called App1 that analyzes customer feedback.  
  
App1 will invoke Azure Language in Foundry Tools from a generative AI agent in Microsoft Foundry.  
  
You need to ensure the agent can access Azure Language text analysis.  
  
What should you configure?', '[{"key":"A","text":"a Foundry model deployment"},{"key":"B","text":"the Azure Language MCP server"},{"key":"C","text":"an Azure Speech in Foundry Tools service endpoint"},{"key":"D","text":"the Azure AI Search index"}]'::jsonb, ARRAY['B']::text[], 'Máy chủ Azure Language MCP kết nối các tác nhân Microsoft Foundry với Ngôn ngữ Azure thông qua Giao thức bối cảnh mô hình và hiển thị phân tích văn bản cũng như các khả năng NLP khác dưới dạng công cụ tác nhân. Việc triển khai mô hình, điểm cuối Giọng nói hoặc chỉ mục Tìm kiếm AI không cung cấp công cụ phân tích văn bản Ngôn ngữ Azure cho tổng đài viên.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-77', 'ai-901', 77, 'For each of the following statements, select **Yes** if the statement is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"To process prompts that contain images, you must deploy a multimodal generative AI model.","correctAnswer":"Yes"},{"id":"2","text":"In the Foundry playground, you can provide an image by uploading a local file or by specifying a publicly accessible URL.","correctAnswer":"Yes"},{"id":"3","text":"A multimodal model can interpret multiple images included in a single prompt.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:Yes', '3:Yes']::text[], 'Lời nhắc bằng hình ảnh yêu cầu một mô hình sáng tạo đa phương thức, có khả năng nhìn. Microsoft Foundry hỗ trợ tải lên hình ảnh trong sân chơi và các URL hình ảnh có thể truy cập công khai; trò chuyện tầm nhìn cho phép tối đa 10 hình ảnh trong một yêu cầu trò chuyện.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-78', 'ai-901', 78, 'You deploy a model named `gpt-image-1` in Microsoft Foundry.  
  
You need to ensure that an application can generate an image from a user prompt by using the OpenAI Images API.  
  
How should you complete the Python code?', '[]'::jsonb, ARRAY[]::text[], 'API hình ảnh OpenAI của Microsoft Foundry tạo hình ảnh từ văn bản bằng thao tác `images.generate` của Python SDK. Tên mẫu `gpt-image-1` đã triển khai và lời nhắc người dùng được cung cấp cho cuộc gọi đó.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-79', 'ai-901', 79, 'You have an AI-based system for loan approvals.  
  
During testing, you find that the system exhibits gender bias.  
  
Which responsible AI principle is violated?', '[{"key":"A","text":"reliability and safety"},{"key":"B","text":"transparency"},{"key":"C","text":"accountability"},{"key":"D","text":"fairness"}]'::jsonb, ARRAY['D']::text[], 'Sự công bằng đòi hỏi hệ thống AI phải tránh những kết quả thiên vị và phân biệt đối xử không công bằng. Định kiến ​​giới trong các quyết định phê duyệt khoản vay có thể dẫn đến sự đối xử bất bình đẳng về giới, vi phạm nguyên tắc này.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-80', 'ai-901', 80, 'In which two situations can speech recognition be used? Each correct answer constitutes a complete solution.  
  
**NOTE:** Each correct selection is worth one point.', '[{"key":"A","text":"creating a transcript of a telephone call or meeting"},{"key":"B","text":"an in-car system that reads text messages aloud"},{"key":"C","text":"creating an automated public address system for a train station"},{"key":"D","text":"providing closed captions for recorded or live videos"}]'::jsonb, ARRAY['A', 'D']::text[], 'Nhận dạng giọng nói là công nghệ chuyển giọng nói thành văn bản: nó có thể tạo bản ghi từ âm thanh cuộc họp hoặc cuộc gọi điện thoại và tạo phụ đề cho cả video trực tiếp và video được ghi trước. Chuyển văn bản thành giọng nói là khả năng thích hợp để đọc to tin nhắn văn bản hoặc tạo thông báo địa chỉ công cộng tự động.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-81', 'ai-901', 81, 'Confirming that machine-learning models do **not** exhibit racial or gender bias is an example of which Microsoft responsible AI principle?', '[{"key":"A","text":"safety"},{"key":"B","text":"reliability"},{"key":"C","text":"fairness"},{"key":"D","text":"privacy and security"}]'::jsonb, ARRAY['C']::text[], 'Sự công bằng đòi hỏi hệ thống AI phải đối xử công bằng với mọi người và các nhóm có thể so sánh được, đồng thời tránh thành kiến ​​​​có hệ thống. Microsoft xác định việc đánh giá tính công bằng giữa các nhóm nhạy cảm, bao gồm cả giới tính và sắc tộc, là một phần của AI có trách nhiệm.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-82', 'ai-901', 82, 'An AI system is deployed to support hiring decisions.  
  
Company policy requires human reviewers to oversee AI-generated recommendations and to retain responsibility for final hiring decisions.  
  
Which Microsoft responsible AI principle does this illustrate?', '[{"key":"A","text":"reliability and safety"},{"key":"B","text":"fairness"},{"key":"C","text":"transparency"},{"key":"D","text":"accountability"}]'::jsonb, ARRAY['D']::text[], 'Trách nhiệm giải trình yêu cầu những người thiết kế và triển khai hệ thống AI phải chịu trách nhiệm về cách thức hoạt động của các hệ thống đó. Trong các quyết định ảnh hưởng đến cuộc sống của con người, chẳng hạn như việc làm, con người nên giữ quyền kiểm soát có ý nghĩa thay vì để hệ thống AI là cơ quan có thẩm quyền cuối cùng.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-83', 'ai-901', 83, 'You are building an application that analyzes uploaded video files by using Azure Content Understanding in Foundry Tools.  
  
You need to ensure that the application extracts structured information from the videos.  
  
What should the application call?', '[{"key":"A","text":"Azure Language in Foundry Tools sentiment analysis"},{"key":"B","text":"the Analyze API in Content Understanding"},{"key":"C","text":"the Image Analysis API in Azure Vision in Foundry Tools"},{"key":"D","text":"Azure OpenAI"}]'::jsonb, ARRAY['B']::text[], 'Azure Content Hiểu phân tích video thông qua bộ phân tích được định cấu hình và trả về nội dung và trường được trích xuất trong kết quả JSON có cấu trúc. Hoạt động Phân tích nội dung của Trình phân tích là API gửi video để trích xuất có cấu trúc này.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-84', 'ai-901', 84, 'You are developing an application that analyzes invoices by using Azure Content Understanding in Foundry Tools.  
  
You have a custom analyzer named `invoiceAnalyzer`.  
  
You need to use the analyzer to process invoice files.  
  
How should you complete the Python code?', '[]'::jsonb, ARRAY[]::text[], 'Hiểu nội dung Azure sử dụng `analyzer_id` để chọn bộ phân tích tùy chỉnh cho hoạt động phân tích. Cung cấp `invoiceAnalyzer` làm đối số đó chạy trình phân tích được đặt tên dựa trên URL tài liệu do `input_url` cung cấp.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-85', 'ai-901', 85, 'For each of the following statements, select Yes if the statement is true. Otherwise, select No.', '{"statements":[{"id":"1","text":"Speech synthesis converts spoken audio into written text.","correctAnswer":"No"},{"id":"2","text":"Speech recognition can detect and transcribe spoken input.","correctAnswer":"Yes"},{"id":"3","text":"Text to speech in Azure Speech in Foundry Tools can translate text input into audible speech in a different language.","correctAnswer":"No"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:No', '2:Yes', '3:No']::text[], 'Tổng hợp giọng nói (chuyển văn bản thành giọng nói) tạo ra âm thanh được nói từ văn bản, trong khi tính năng nhận dạng giọng nói sẽ chuyển đổi âm thanh được nói thành văn bản. Tính năng chuyển văn bản thành giọng nói không dịch văn bản sang ngôn ngữ khác; bản dịch là một khả năng Azure Speech riêng biệt.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-86', 'ai-901', 86, 'Which two situations are examples of a natural language processing workload? Each correct answer provides a complete solution.  
  
**NOTE:** Each correct selection is worth one point.', '[{"key":"A","text":"monitoring the temperature of machinery to turn on a fan when the temperature reaches a specific threshold"},{"key":"B","text":"assembly line machinery that autonomously inserts headlamps into cars"},{"key":"C","text":"a smart device in the home that responds to questions such as, “What will the weather be like today?”"},{"key":"D","text":"an agent on a website that uses a knowledge base to interactively respond to users’ questions"}]'::jsonb, ARRAY['C', 'D']::text[], 'Xử lý ngôn ngữ tự nhiên cho phép các hệ thống hiểu và trả lời các câu hỏi bằng ngôn ngữ của con người. Trợ lý giọng nói trả lời các câu hỏi và tác nhân trang web trả lời người dùng một cách tương tác từ cơ sở kiến ​​thức là khối lượng công việc NLP.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-87', 'ai-901', 87, 'You have a Python application that extracts invoice fields by using Azure Content Understanding in Foundry Tools.  
  
You submit a PDF for analysis.  
  
What must the application do to obtain the results?', '[{"key":"A","text":"Repeatedly call begin_analyze() with the same inputs to force a synchronous response."},{"key":"B","text":"Send a GET request to the Microsoft Foundry endpoint to download the analyzer schema."},{"key":"C","text":"Poll the operation results until the asynchronous analysis job succeeds."},{"key":"D","text":"Use optical character recognition (OCR) to parse the text from the PDF and map the fields in the code."}]'::jsonb, ARRAY['C']::text[], 'Phân tích Hiểu nội dung Azure chạy dưới dạng hoạt động lâu dài không đồng bộ. Khách hàng phải thăm dò kết quả hoạt động cho đến khi quá trình phân tích hoàn tất thành công, lúc đó các trường trích xuất có cấu trúc sẽ có sẵn.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-88', 'ai-901', 88, 'You have a Microsoft Foundry project containing a vision-enabled model deployment.  
  
You need to develop an application that uses the Azure OpenAI client library to send prompts to the model.  
  
How should you complete the Python code?', '[]'::jsonb, ARRAY[]::text[], 'API phản hồi Azure OpenAI sử dụng `client.responses.create()` và chấp nhận cả `model` và `input`. Việc triển khai có khả năng hiển thị như GPT-4o có thể nhận được nội dung đa phương thức phù hợp thông qua đầu vào đó.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-89', 'ai-901', 89, 'For each statement, select **Yes** if it is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"Generative AI models predict the next token in a sequence based on patterns learned during training.","correctAnswer":"Yes"},{"id":"2","text":"A system prompt can be used to influence the behavior and tone of the responses generated by a generative AI model.","correctAnswer":"Yes"},{"id":"3","text":"Increasing the Temperature parameter makes the responses generated by generative AI models more deterministic and consistent.","correctAnswer":"No"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:Yes', '3:No']::text[], 'Các mô hình ngôn ngữ sáng tạo tạo ra văn bản bằng cách dự đoán các mã thông báo liên tiếp. Lời nhắc của hệ thống cung cấp các hướng dẫn ảnh hưởng đến hành vi và giọng điệu phản hồi. Nhiệt độ cao hơn làm tăng tính ngẫu nhiên trong việc lựa chọn mã thông báo, khiến kết quả đầu ra trở nên đa dạng hơn và ít mang tính xác định hơn.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-90', 'ai-901', 90, 'Question 90', '[]'::jsonb, ARRAY[]::text[], 'Khối lượng công việc lời nói cung cấp khả năng chuyển lời nói thành văn bản, giúp chuyển các yêu cầu nói của khách hàng thành văn bản viết.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-91', 'ai-901', 91, 'You have a Microsoft Foundry project that includes a vision-enabled GPT model deployment.  
  
You need to build an application that sends an image and a text-based question to the model in one request.  
  
What should you use?', '[{"key":"A","text":"the Azure OpenAI Images API endpoint only"},{"key":"B","text":"the Speech to text REST API"},{"key":"C","text":"the Image Analysis REST API"},{"key":"D","text":"the Azure OpenAI Responses API"}]'::jsonb, ARRAY['D']::text[], 'API phản hồi Azure OpenAI hỗ trợ đầu vào đa phương thức cho các mô hình GPT hỗ trợ thị giác bằng cách đặt các phần nội dung `input_text` và `input_image` trong cùng một yêu cầu, cho phép mô hình trả lời câu hỏi văn bản về hình ảnh.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-92', 'ai-901', 92, 'You are developing an AI-based loan approval application.  
  
You must ensure that the application records why a loan is approved or rejected and makes that report available to the applicant.  
  
This is an example of which Microsoft responsible AI principle?', '[{"key":"A","text":"transparency"},{"key":"B","text":"accountability"},{"key":"C","text":"fairness"},{"key":"D","text":"inclusiveness"}]'::jsonb, ARRAY['A']::text[], 'Tính minh bạch yêu cầu các hệ thống AI đưa ra những lời giải thích dễ hiểu về hành vi và quyết định của chúng. Microsoft xác định cụ thể việc giải thích lý do tại sao đơn đăng ký khoản vay của khách hàng được phê duyệt hoặc bị từ chối dưới dạng giải thích mô hình cục bộ theo nguyên tắc minh bạch.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-93', 'ai-901', 93, 'You intend to create an AI application that uses Azure OpenAI in Foundry Models. The solution requires a specified amount of throughput to be allocated. Which deployment type should you use?', '[{"key":"A","text":"provisioned"},{"key":"B","text":"standard"},{"key":"C","text":"global batch"},{"key":"D","text":"data zone standard"}]'::jsonb, ARRAY['A']::text[], 'Các hoạt động triển khai được cung cấp sẽ phân bổ một lượng công suất xử lý mô hình cụ thể bằng cách sử dụng các đơn vị thông lượng được cung cấp (PTU), cung cấp công suất cần thiết cho các yêu cầu thông lượng đã xác định.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-94', 'ai-901', 94, 'You are building an application that summarizes customer comments by using Azure Language in Foundry Tools.  
  
You need to install the Azure Language SDK.  
  
Which Python package should be installed?', '[{"key":"A","text":"azure-ai-translation-text"},{"key":"B","text":"azure-ai-textanalytics"},{"key":"C","text":"azure-search-documents"},{"key":"D","text":"langchain"}]'::jsonb, ARRAY['B']::text[], 'Phân tích và tóm tắt văn bản Ngôn ngữ AI Azure sử dụng thư viện máy khách Phân tích văn bản Azure cho Python, được cài đặt dưới dạng `azure-ai-textanalytics`.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-95', 'ai-901', 95, 'For each of these statements, select **Yes** when the statement is true. Otherwise, select **No**.', '{"statements":[{"id":"1","text":"To use the Microsoft Foundry SDK, you must manually construct HTTP requests to the model endpoint.","correctAnswer":"No"},{"id":"2","text":"When using the Microsoft Foundry SDK in an application, you must create a separate web service to interact with a deployed model.","correctAnswer":"No"},{"id":"3","text":"In the Microsoft Foundry SDK, the AIProjectClient class provides programmatic access to a deployed project and its connected resources.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:No', '2:No', '3:Yes']::text[], 'SDK Foundry cung cấp các thư viện máy khách để xử lý các yêu cầu dịch vụ, do đó, việc xây dựng các yêu cầu HTTP điểm cuối mô hình theo cách thủ công là không cần thiết. Ứng dụng có thể sử dụng trực tiếp ứng dụng khách SDK để làm việc với mô hình đã triển khai; một dịch vụ web riêng biệt là không cần thiết. AIProjectClient cung cấp quyền truy cập vào các khả năng của dự án Foundry, bao gồm các hoạt động dựa trên mô hình được triển khai và tài nguyên được kết nối.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-96', 'ai-901', 96, 'Question 96', '[]'::jsonb, ARRAY[]::text[], 'Một mô hình AI tổng quát đã triển khai được truy cập để suy luận thông qua điểm cuối API của nó; ứng dụng khách gọi điểm cuối đó để gửi yêu cầu và nhận phản hồi.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-97', 'ai-901', 97, 'Which three Microsoft guiding principles apply to responsible AI? Each correct answer represents a complete solution.  
  
> **NOTE:** Each correct selection is worth one point.', '[{"key":"A","text":"opinionatedness"},{"key":"B","text":"decisiveness"},{"key":"C","text":"fairness"},{"key":"D","text":"reliability and safety"},{"key":"E","text":"inclusiveness"},{"key":"F","text":"knowledgeability"}]'::jsonb, ARRAY['C', 'D', 'E']::text[], 'Tiêu chuẩn AI có trách nhiệm của Microsoft dựa trên sáu nguyên tắc, bao gồm tính công bằng, độ tin cậy và an toàn cũng như tính toàn diện. Những nguyên tắc này thúc đẩy đối xử công bằng, hành vi hệ thống an toàn và đáng tin cậy cũng như các hệ thống AI phục vụ đầy đủ mọi người. [What is Responsible AI? — Microsoft Learn](https://learn.microsoft.com/en-us/azure/machine-learning/concept-responsible-ai?view=azureml-api-2)', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-98', 'ai-901', 98, 'Which natural language processing feature can identify the primary talking points in customer feedback surveys?', '[{"key":"A","text":"translation"},{"key":"B","text":"language detection"},{"key":"C","text":"entity recognition"},{"key":"D","text":"key phrase extraction"}]'::jsonb, ARRAY['D']::text[], 'Trích xuất cụm từ khóa đánh giá văn bản phi cấu trúc và trả về các cụm từ chính thể hiện các khái niệm hoặc chủ đề chính của văn bản đó, giúp văn bản này phù hợp để xác định các điểm thảo luận chính trong khảo sát phản hồi của khách hàng.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-99', 'ai-901', 99, 'For each statement, select **Yes** when it is true; otherwise, select **No**.', '{"statements":[{"id":"1","text":"All AI models can analyze and generate images.","correctAnswer":"No"},{"id":"2","text":"A vision-enabled generative AI model can extract text from images.","correctAnswer":"Yes"},{"id":"3","text":"A multimodal model can process prompts that include both text and images.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:No', '2:Yes', '3:Yes']::text[], 'Các mô hình AI khác nhau tùy theo kiến ​​trúc và đào tạo, vì vậy việc phân tích hình ảnh và tạo hình ảnh không phải là những khả năng phổ biến. AI tổng hợp hỗ trợ thị giác có thể đọc văn bản trong hình ảnh và các mô hình đa phương thức được thiết kế để xử lý các đầu vào như văn bản và hình ảnh cùng nhau.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-100', 'ai-901', 100, 'Match each description with its corresponding Microsoft Foundry tool.  
  
Each description may be used once, more than once, or not at all.', '{"statements":[{"id":"speech_recognition","text":"Speech recognition:","correctAnswer":"C"},{"id":"speech_synthesis","text":"Speech synthesis:","correctAnswer":"B"}],"choices":[{"key":"A","text":"Extracts entities from the output"},{"key":"B","text":"Generates spoken output"},{"key":"C","text":"Transcribes spoken input"}]}'::jsonb, ARRAY['speech_recognition=C', 'speech_synthesis=B']::text[], 'Nhận dạng giọng nói chuyển đổi âm thanh giọng nói thành văn bản, trong khi tổng hợp giọng nói chuyển đổi văn bản thành âm thanh nói. Trích xuất thực thể là một khả năng xử lý ngôn ngữ tự nhiên riêng biệt, không phải chức năng giọng nói.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-101', 'ai-901', 101, 'For each of the following statements, select Yes if the statement is true. Otherwise, select No.', '{"statements":[{"id":"1","text":"A single method of user input for an AI system provides an inclusive experience.","correctAnswer":"No"},{"id":"2","text":"Increasing the overall number of users that use an AI system supports an inclusive experience.","correctAnswer":"No"},{"id":"3","text":"Designing an AI system that accommodates users that have different language preferences supports inclusiveness.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:No', '2:No', '3:Yes']::text[], 'Thiết kế AI toàn diện đáp ứng nhu cầu và khả năng đa dạng của người dùng. Việc dựa vào một phương thức nhập liệu có thể loại trừ người dùng và chỉ số lượng người dùng không tạo nên một hệ thống toàn diện. Việc cung cấp các tùy chọn ngôn ngữ khác nhau giúp giảm rào cản sử dụng và hỗ trợ tính toàn diện.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-102', 'ai-901', 102, 'You have a Microsoft Foundry project that includes a vision-enabled chat model deployment.  
  
You are building a Python application that uses the responses API. The application sends a request containing a user prompt and a local JPEG image.  
  
You need to include the local image in that request.  
  
Which value should you use for the image input?', '[{"key":"A","text":"data:image/jpeg;base64,"},{"key":"B","text":"C:\\images\\photo.jpg"},{"key":"C","text":"file:///C:/images/photo.jpg"},{"key":"D","text":"https://.blob.core.windows.net//.jpg"}]'::jsonb, ARRAY['A']::text[], 'JPEG cục bộ phải được mã hóa Base64 và được cung cấp dưới dạng URI dữ liệu nội tuyến cho giá trị `input_image`: `data:image/jpeg;base64,`, theo sau là dữ liệu hình ảnh được mã hóa. API phản hồi không sử dụng đường dẫn hệ thống tệp cục bộ hoặc URI `file://` làm URL hình ảnh.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-103', 'ai-901', 103, 'Question 103', '[]'::jsonb, ARRAY[]::text[], 'Các mô hình đa phương thức xử lý và liên kết nhiều phương thức dữ liệu, chẳng hạn như văn bản và hình ảnh. Nhiệm vụ hiểu hình ảnh bao gồm việc phát hiện các đối tượng trong một hình ảnh.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-104', 'ai-901', 104, 'You have a Microsoft Foundry project that includes a deployed generative AI model.  
  
You need to build an application by using the Microsoft Foundry SDK to send chat prompts to that deployed model.  
  
Which information must the application include?', '[{"key":"A","text":"Model training dataset, exported playground session history, and Foundry project display name"},{"key":"B","text":"Exported playground session history, endpoint URL and task type"},{"key":"C","text":"Credentials, endpoint URL, and model deployment name"},{"key":"D","text":"Foundry project display name, model training dataset, and task type"}]'::jsonb, ARRAY['C']::text[], 'Việc gọi mô hình Microsoft Foundry đã triển khai yêu cầu thông tin xác thực, URL điểm cuối của dịch vụ hoặc dự án để định tuyến yêu cầu và tên triển khai mô hình để chọn mô hình đã triển khai. Microsoft Learn chỉ định rằng các yêu cầu trò chuyện sử dụng tên triển khai làm giá trị mô hình và sử dụng quyền truy cập được xác thực dựa trên điểm cuối.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-105', 'ai-901', 105, 'A generative AI model is being deployed to a Microsoft Foundry project.  
  
You allocate a higher tokens-per-minute (TPM) value to the model.  
  
What is the effect of this change?', '[{"key":"A","text":"The Azure region availability of the model changes."},{"key":"B","text":"The model generates longer responses."},{"key":"C","text":"The model generates shorter responses and additional source citations."},{"key":"D","text":"The speed and scale at which the model deployment can process inputs changes."}]'::jsonb, ARRAY['D']::text[], 'Phân bổ TPM cao hơn sẽ tăng giới hạn tốc độ mã thông báo của quá trình triển khai, cho phép triển khai xử lý nhiều mã thông báo hơn và khối lượng yêu cầu mỗi phút trước khi điều chỉnh. Nó thay đổi thông lượng và quy mô triển khai, chứ không phải tính sẵn có của khu vực hoặc đặc điểm phản hồi của mô hình.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-106', 'ai-901', 106, 'You intend to deploy a generative AI model to a Microsoft Foundry project in the East US Azure region.  
  
What should you verify first?', '[{"key":"A","text":"Model availability"},{"key":"B","text":"the token limit"},{"key":"C","text":"REST API support"},{"key":"D","text":"the authentication method"}]'::jsonb, ARRAY['A']::text[], 'Tính khả dụng của mô hình Microsoft Foundry thay đổi tùy theo nhà cung cấp, loại triển khai và khu vực Azure. Một mô hình phải có sẵn ở miền Đông Hoa Kỳ trước khi có thể triển khai ở đó; chi tiết cấu hình như giới hạn mã thông báo, hỗ trợ API và xác thực không khắc phục được việc triển khai khu vực không được hỗ trợ.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-107', 'ai-901', 107, 'You have 100 instructional videos that **do not** contain any audio. Each instructional video includes a script.  
  
You need to create a narration audio file for every video from its script.  
  
Which workload type should you use?', '[{"key":"A","text":"translation"},{"key":"B","text":"speech recognition"},{"key":"C","text":"language modeling"},{"key":"D","text":"speech synthesis"}]'::jsonb, ARRAY['D']::text[], 'Tổng hợp giọng nói chuyển đổi văn bản viết thành âm thanh nói tổng hợp, tạo ra các tệp tường thuật trực tiếp từ tập lệnh video.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-108', 'ai-901', 108, 'Which type of Azure AI workload should be used to create illustrations from an article''s text?', '[{"key":"A","text":"generative AI"},{"key":"B","text":"Azure Document Intelligence in Foundry Tools"},{"key":"C","text":"computer vision"},{"key":"D","text":"natural language processing"}]'::jsonb, ARRAY['A']::text[], 'AI sáng tạo có thể tạo hình ảnh mới từ lời nhắc bằng văn bản, khiến nó trở thành khối lượng công việc phù hợp để tạo hình minh họa dựa trên văn bản của bài viết.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-109', 'ai-901', 109, 'Question 109', '[]'::jsonb, ARRAY[]::text[], 'AIProjectClient là ứng dụng khách trong phạm vi dự án Microsoft Foundry. Nó hiển thị các hoạt động triển khai, tác nhân và chỉ mục; ChatCompletionsClient được sử dụng để suy luận hoàn thành trò chuyện thay vì quản lý các tài nguyên dự án này.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-110', 'ai-901', 110, 'Question 110', '[]'::jsonb, ARRAY[]::text[], 'Azure Speech trong Foundry Tools cung cấp chức năng chuyển giọng nói thành văn bản, chuyển âm thanh được nói thành văn bản.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-111', 'ai-901', 111, 'For each of the following statements, select Yes if the statement is true. Otherwise, select No.', '{"statements":[{"id":"1","text":"An Azure Content Understanding in Foundry Tools analyzer returns results in the HTML format.","correctAnswer":"No"},{"id":"2","text":"The Content Understanding REST API analyzes content synchronously and returns results in the same response.","correctAnswer":"No"},{"id":"3","text":"Azure Content Understanding in Foundry Tools can extract structured information from documents, images, audio, and video files.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:No', '2:No', '3:Yes']::text[], 'Hiểu nội dung trả về kết quả JSON có cấu trúc thay vì HTML. Quy trình phân tích REST thông thường của nó là không đồng bộ, trả về Vị trí hoạt động được thăm dò để truy xuất kết quả. Nó hỗ trợ trích xuất đa phương thức từ tài liệu, hình ảnh, âm thanh và video.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-112', 'ai-901', 112, 'For each statement, select **Yes** if it is true; otherwise, select **No**.', '{"statements":[{"id":"1","text":"Whisper models in Azure OpenAI are used to convert speech to text.","correctAnswer":"Yes"},{"id":"2","text":"Embedding models in Azure OpenAI are used to convert text into numeric vectors.","correctAnswer":"Yes"},{"id":"3","text":"GPT-4.1 models in Azure OpenAI are used to generate images based on natural language prompts.","correctAnswer":"No"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:Yes', '2:Yes', '3:No']::text[], 'Whisper thực hiện chuyển lời nói thành văn bản. Các mô hình nhúng tạo ra các biểu diễn vectơ của văn bản cho khối lượng công việc tương tự và tìm kiếm ngữ nghĩa. GPT-4.1 hỗ trợ xử lý văn bản và hình ảnh nhưng các mô hình tạo hình ảnh chuyên dụng được sử dụng để tạo hình ảnh từ lời nhắc.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-113', 'ai-901', 113, 'You are developing a chatbot that will use natural language processing (NLP) to carry out the following actions from a user''s text input:  
  
- Accept customer orders.  
- Retrieve support documents.  
- Retrieve order-status updates.  
  
Which type of NLP should you use?', '[{"key":"A","text":"sentiment analysis"},{"key":"B","text":"named entity recognition"},{"key":"C","text":"translation"},{"key":"D","text":"language understanding"}]'::jsonb, ARRAY['D']::text[], 'Khả năng hiểu ngôn ngữ xác định mục đích được thể hiện trong văn bản của người dùng, cho phép ứng dụng đàm thoại phân biệt các yêu cầu đặt hàng, truy xuất nội dung hỗ trợ hoặc nhận bản cập nhật trạng thái đơn hàng và định tuyến từng yêu cầu đến hành động thích hợp. Nó cũng có thể trích xuất các chi tiết liên quan cần thiết để thực hiện mục đích đó.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-114', 'ai-901', 114, 'You have a Microsoft Foundry project that includes a vision-enabled model deployment.  
  
You need to create a prompt that makes sure the model generates a relevant, useful response.  
  
What should the prompt include?', '[{"key":"A","text":"the version number of the model"},{"key":"B","text":"a description of the task"},{"key":"C","text":"the deployment name of the model"},{"key":"D","text":"a dataset ID for the image"}]'::jsonb, ARRAY['B']::text[], 'Mô tả nhiệm vụ cung cấp cho mô hình hỗ trợ tầm nhìn các hướng dẫn cụ thể và bối cảnh cần thiết để tập trung phân tích và tạo ra phản hồi thích hợp. Microsoft Learn khuyên bạn nên tạo thông báo hệ thống cụ thể cho tác vụ để tránh những phản hồi không hữu ích.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-115', 'ai-901', 115, 'You are building a lightweight application that will call an agent programmatically by using the Microsoft Foundry SDK.  
  
You need to determine the agent ID.  
  
What should you do?', '[{"key":"A","text":"In the model catalog, open the model card and copy the model family name."},{"key":"B","text":"the Foundry portal, copy the project name."},{"key":"C","text":"In the Foundry tool catalog, copy the tool name used by the agent."},{"key":"D","text":"In the Foundry playground, select Code, and view the .env variables."}]'::jsonb, ARRAY['D']::text[], 'ID tác nhân là mã nhận dạng duy nhất cần có để nhắm mục tiêu một tác nhân cụ thể trong lệnh gọi SDK có lập trình. Chế độ xem Mã được tạo của sân chơi Foundry hiển thị cấu hình tác nhân dưới dạng các biến môi trường, cho phép ứng dụng sử dụng mã định danh đó; Tên mô hình, dự án và công cụ không xác định duy nhất tác nhân.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-116', 'ai-901', 116, 'You need to create an AI solution that answers user queries with detailed written explanations.  
  
Which type of AI model should you use?', '[{"key":"A","text":"an image generation model"},{"key":"B","text":"a speech recognition model"},{"key":"C","text":"a text generation model"},{"key":"D","text":"an embedding model"}]'::jsonb, ARRAY['C']::text[], 'Các mô hình tạo văn bản tạo ra phản hồi bằng văn bản bằng ngôn ngữ tự nhiên, khiến chúng phù hợp để trả lời các truy vấn của người dùng kèm theo giải thích chi tiết.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-117', 'ai-901', 117, 'You are building an application that continuously transcribes speech from a default microphone by using Azure Speech in Microsoft Foundry Tools.  
  
You need to carry out speech-to-text transcription from the microphone.  
  
Which Python class should you use?', '[{"key":"A","text":"SpeechRecognizer"},{"key":"B","text":"SpeechSynthesizer"},{"key":"C","text":"SpeechConfig"},{"key":"D","text":"AudioOutputConfig"}]'::jsonb, ARRAY['A']::text[], '`SpeechRecognizer` thực hiện nhận dạng giọng nói thành văn bản và hỗ trợ nhận dạng liên tục. Nó có thể được xây dựng với cấu hình âm thanh sử dụng micrô mặc định; `SpeechConfig` định cấu hình dịch vụ, trong khi cấu hình bộ tổng hợp và đầu ra âm thanh dành cho đầu ra giọng nói.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-118', 'ai-901', 118, 'You are designing an AI system that empowers everyone, including individuals with hearing, visual, and other impairments.  
  
Which Microsoft guiding principle for responsible AI does this illustrate?', '[{"key":"A","text":"accountability"},{"key":"B","text":"reliability and safety"},{"key":"C","text":"fairness"},{"key":"D","text":"inclusiveness"}]'::jsonb, ARRAY['D']::text[], 'Tính toàn diện đòi hỏi các hệ thống AI phải được thiết kế và có thể tiếp cận được với đầy đủ những người mà chúng phục vụ, bao gồm cả người khuyết tật và những người bị suy yếu khác.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-119', 'ai-901', 119, 'Which task can be carried out using the Azure Vision in Foundry Tools service?', '[{"key":"A","text":"creating thumbnails for training videos"},{"key":"B","text":"extracting key phrases from documents"},{"key":"C","text":"identifying breeds of animals in live video streams"},{"key":"D","text":"extracting data from handwritten letters"}]'::jsonb, ARRAY['D']::text[], 'Azure Vision trong Foundry Tools bao gồm Đọc OCR, tính năng này trích xuất văn bản in và viết tay từ hình ảnh và tài liệu, bao gồm cả chữ cái. Điều này cho phép trích xuất dữ liệu từ các chữ viết tay.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-120', 'ai-901', 120, 'You are developing an AI solution that processes customer information.  
  
Which task exemplifies the Microsoft responsible AI principle of privacy and security?', '[{"key":"A","text":"Encrypt stored customer data and restrict system access by using role-based controls."},{"key":"B","text":"Provide explanations about how the system generates predictions."},{"key":"C","text":"Test the system under unexpected conditions to prevent harmful failures."},{"key":"D","text":"Evaluate model outputs across demographic groups to reduce bias."}]'::jsonb, ARRAY['A']::text[], 'Mã hóa dữ liệu khách hàng được lưu trữ và thực thi các biện pháp kiểm soát truy cập dựa trên vai trò bảo vệ thông tin nhạy cảm khỏi bị truy cập trái phép, hỗ trợ trực tiếp quyền riêng tư và bảo mật. Hướng dẫn của Microsoft mô tả mã hóa nội dung của khách hàng ở trạng thái lưu trữ và role-based access control là biện pháp bảo vệ dữ liệu.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-121', 'ai-901', 121, 'In the Microsoft Foundry portal, you create an agent called Agent1 and then deploy it.  
  
You open the Foundry playground to test Agent1.  
  
What does the playground use to ensure that testing reflects production behavior?', '[{"key":"A","text":"a default configuration generated by the playground"},{"key":"B","text":"the model’s base behavior without any agent instructions or tools"},{"key":"C","text":"the configuration of Agent1"},{"key":"D","text":"the last saved configuration draft that was NOT deployed"}]'::jsonb, ARRAY['C']::text[], 'Sân chơi kiểm tra tác nhân được triển khai bằng cách sử dụng cấu hình của tác nhân đó, do đó việc lựa chọn mô hình, hướng dẫn, công cụ và hành vi được định cấu hình khác của nó sẽ phù hợp với tác nhân sản xuất được triển khai.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-122', 'ai-901', 122, 'You need to deploy a generative AI model to a Microsoft Foundry project.  
  
Which factor should you use to determine which model type can be deployed to the project?', '[{"key":"A","text":"the token size"},{"key":"B","text":"Azure region availability"},{"key":"C","text":"the authentication method"},{"key":"D","text":"REST API support"}]'::jsonb, ARRAY['B']::text[], 'Tính khả dụng của mô hình tùy theo khu vực. Dự án Microsoft Foundry và tài nguyên của nó phải nằm trong khu vực được hỗ trợ để triển khai mô hình đã chọn, do đó, tính khả dụng của khu vực Azure sẽ xác định xem loại mô hình đó có thể được triển khai hay không.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-123', 'ai-901', 123, 'Extracting text from images is an example of which type of AI capability?', '[{"key":"A","text":"object detection"},{"key":"B","text":"text analysis"},{"key":"C","text":"optical character recognition (OCR)"},{"key":"D","text":"image description"}]'::jsonb, ARRAY['C']::text[], 'Nhận dạng ký tự quang học (OCR) phát hiện và chuyển đổi văn bản có trong hình ảnh thành văn bản có thể đọc được bằng máy.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-124', 'ai-901', 124, 'Match responsible-AI principles with the appropriate requirements.  
  
A principle may be used once, more than once, or not at all.', '{"statements":[{"id":"slot1","text":"The system must not discriminate based on gender, race, or age.","correctAnswer":"A"},{"id":"slot2","text":"Personal data must be visible only to approved users.","correctAnswer":"B"},{"id":"slot3","text":"Automated decision-making processes must be recorded so that approved users can identify why a decision was made.","correctAnswer":"D"}],"choices":[{"key":"A","text":"Fairness"},{"key":"B","text":"Privacy and security"},{"key":"C","text":"Reliability and safety"},{"key":"D","text":"Transparency"}]}'::jsonb, ARRAY['slot1=A', 'slot2=B', 'slot3=D']::text[], 'Sự công bằng đòi hỏi hệ thống AI phải tránh sự thiên vị có hệ thống và đối xử khác biệt với những người có thể so sánh được. Quyền riêng tư và bảo mật bảo vệ thông tin cá nhân thông qua các ranh giới dữ liệu và kiểm soát truy cập thích hợp. Tính minh bạch yêu cầu việc ra quyết định phải dễ hiểu và có thể xem xét được, do đó, hồ sơ quyết định tiết lộ lý do đưa ra quyết định tự động đáp ứng nguyên tắc này.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-125', 'ai-901', 125, 'For each of the following statements, select Yes if the statement is true. Otherwise, select No.', '{"statements":[{"id":"1","text":"A summarization model is used to transcribe spoken audio into written text.","correctAnswer":"No"},{"id":"2","text":"A chat completion model can generate vector embeddings for semantic tasks.","correctAnswer":"No"},{"id":"3","text":"An embedding model can generate vector representations of the provided input.","correctAnswer":"Yes"}],"choices":[{"key":"Yes","text":"Yes"},{"key":"No","text":"No"}]}'::jsonb, ARRAY['1:No', '2:No', '3:Yes']::text[], 'Tóm tắt tạo ra sự trình bày ngắn gọn về văn bản hoặc cuộc hội thoại; nó không phải là phiên âm từ giọng nói sang văn bản. Các mô hình hoàn thành cuộc trò chuyện trả về các tin nhắn trò chuyện đã tạo, trong khi các mô hình nhúng tạo ra các vectơ số cho các tác vụ so sánh ngữ nghĩa như tìm kiếm, phân cụm và đề xuất. API nhúng trả về một vectơ đại diện cho đầu vào được cung cấp.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-126', 'ai-901', 126, 'Question 126', '[]'::jsonb, ARRAY[]::text[], 'Các mô hình thị giác máy tính xử lý dữ liệu trực quan để nhận dạng và phát hiện các đối tượng trong hình ảnh.', 'General', ARRAY['AI-901', 'General']::text[], NULL, 'published'),
  ('ai901-127', 'ai-901', 127, 'Consider the following REST API request.  
  
![Question Image](https://cdn.examcademy.com/images/questions/1787372409659-t37ibexi.png)  
  
Which Azure OpenAI model should be used to process this request?', '[{"key":"A","text":"DALL-E"},{"key":"B","text":"Codex"},{"key":"C","text":"GPT-4.1"},{"key":"D","text":"Whisper"}]'::jsonb, ARRAY['A']::text[], 'DALL-E là mô hình tạo hình ảnh Azure OpenAI. Lời nhắc hình ảnh văn bản có `size`, `n` và kiểu `vivid` là một yêu cầu tạo hình ảnh; `vivid` là tùy chọn kiểu DALL-E 3 và DALL-E 3 yêu cầu `n` được đặt thành 1.', 'General', ARRAY['AI-901', 'General']::text[], 'https://cdn.examcademy.com/images/questions/1787372409659-t37ibexi.png', 'published'),
  ('ai901-128', 'ai-901', 128, 'You have the process depicted in the following exhibit.  
  
![Question Image](https://cdn.examcademy.com/images/questions/1787372409217-g7ksmkm3.png)  
  
Which type of AI solution is illustrated in the diagram?', '[{"key":"A","text":"a sentiment analysis solution"},{"key":"B","text":"a computer vision application"},{"key":"C","text":"an agent"},{"key":"D","text":"a machine learning model"}]'::jsonb, ARRAY['C']::text[], 'Giao diện đàm thoại cơ sở tri thức nhận câu hỏi của người dùng, truy vấn cơ sở tri thức thông qua API và trả về câu trả lời. Đây là một giải pháp đại lý (chatbot). Microsoft mô tả QnA Maker cung cấp lớp đàm thoại trên nền tảng kiến ​​thức cho các ứng dụng khách đàm thoại như chatbot.', 'General', ARRAY['AI-901', 'General']::text[], 'https://cdn.examcademy.com/images/questions/1787372409217-g7ksmkm3.png', 'published')
